#!/usr/bin/env node
// oh-my-t3code worktree setup runner
// Generated by `omt worktree setup`. T3 Code runs it in each new worktree before the agent starts.
// It installs this checkout's dependencies with Bun or pnpm into a global virtual store.
// It uses only Node built-ins, so it works without oh-my-t3code installed.
import { spawnSync } from "node:child_process";
import { existsSync, lstatSync, readFileSync, readdirSync, realpathSync, statSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const RUNNER_MARKER = "oh-my-t3code worktree setup runner";
export const MINIMUM_VERSIONS = { bun: "1.4.3", pnpm: "10.34.5" };
export const PNPM_CANONICAL_GLOBAL_STORE = "11.23.0";
export const LOCKFILES = { pnpm: ["pnpm-lock.yaml"], bun: ["bun.lock", "bun.lockb"] };
const OTHER_LOCKFILES = { npm: ["package-lock.json", "npm-shrinkwrap.json"], yarn: ["yarn.lock"] };
const SUPPORTED = ["pnpm", "bun"];

// Settings that stop Corepack and pnpm from downloading or switching package-manager versions.
export const NO_DOWNLOAD_ENV = {
  COREPACK_ENABLE_NETWORK: "0",
  npm_config_manage_package_manager_versions: "false",
  npm_config_package_manager_strict_version: "true",
  pnpm_config_pm_on_fail: "error",
};

// Exact numeric versions only, such as 10.12.1. Ranges and tags return undefined.
export function parseVersion(text) {
  const match = /^(\d+)\.(\d+)\.(\d+)$/.exec(String(text).trim());
  return match === null ? undefined : [Number(match[1]), Number(match[2]), Number(match[3])];
}

export function compareVersions(a, b) {
  const left = typeof a === "string" ? parseVersion(a) : a;
  const right = typeof b === "string" ? parseVersion(b) : b;
  if (left === undefined || right === undefined) throw new Error(`not an exact version: ${a} or ${b}`);
  for (let i = 0; i < 3; i++) {
    if (left[i] !== right[i]) return left[i] < right[i] ? -1 : 1;
  }
  return 0;
}

function minimumVersion(manager, version) {
  return manager === "pnpm" && parseVersion(version)?.[0] === 11
    ? "11.11.0"
    : MINIMUM_VERSIONS[manager];
}

function readText(path) {
  try {
    return readFileSync(path, "utf8");
  } catch (error) {
    if (error?.code === "ENOENT" || error?.code === "ENOTDIR") return undefined;
    throw error;
  }
}

function isFile(path) {
  try {
    return statSync(path).isFile();
  } catch {
    return false;
  }
}

function blocked(message, action) {
  return { status: "blocked", message, ...(action === undefined ? {} : { action }) };
}

// `name@version`, with an optional `+<integrity>` suffix that Corepack writes.
function fromPackageManagerField(value) {
  if (typeof value !== "string") return { error: "packageManager is not a string" };
  const match = /^(@?[^@\s]+)@([^\s]+)$/.exec(value.trim());
  if (match === null) return { error: `packageManager "${value}" is not in the form <name>@<version>` };
  return { name: match[1], spec: match[2].replace(/\+.*$/, ""), source: "packageManager" };
}

function fromDevEngines(value) {
  const entries = Array.isArray(value) ? value : [value];
  if (entries.length === 0) return { error: "devEngines.packageManager is an empty list" };
  const found = [];
  for (const entry of entries) {
    if (entry === null || typeof entry !== "object" || typeof entry.name !== "string" || entry.name.trim() === "") {
      return { error: "devEngines.packageManager needs a name in each entry" };
    }
    if (entry.version !== undefined && typeof entry.version !== "string") {
      return { error: "devEngines.packageManager version is not a string" };
    }
    found.push({ name: entry.name.trim(), spec: entry.version?.trim(), source: "devEngines.packageManager" });
  }
  const names = new Set(found.map((entry) => entry.name));
  if (names.size > 1) return { error: `devEngines.packageManager lists more than one manager: ${[...names].join(", ")}` };
  if (found.length > 1) return { error: "devEngines.packageManager lists the same manager more than once" };
  return found[0];
}

function lockfilesOf(root, names) {
  return names.filter((name) => isFile(join(root, name)));
}

// Finds the package manager of the checkout from package.json and the lockfiles.
// Returns { status: "ok", manager, lockfile, version?, declaredBy? }, { status: "none", message },
// or { status: "blocked", message, action? }.
export function detectManager(root) {
  const text = readText(join(root, "package.json"));
  let pkg;
  if (text !== undefined) {
    try {
      pkg = JSON.parse(text.charCodeAt(0) === 0xfeff ? text.slice(1) : text);
    } catch (error) {
      return blocked(`package.json is not valid JSON: ${error.message}`, "fix package.json");
    }
    if (pkg === null || typeof pkg !== "object" || Array.isArray(pkg)) return blocked("package.json is not a JSON object", "fix package.json");
  }
  const declarations = [];
  if (pkg?.packageManager !== undefined) declarations.push(fromPackageManagerField(pkg.packageManager));
  const engines = pkg?.devEngines;
  if (engines !== null && typeof engines === "object" && engines.packageManager !== undefined) {
    declarations.push(fromDevEngines(engines.packageManager));
  }
  for (const declaration of declarations) {
    if (declaration.error !== undefined) return blocked(declaration.error, "fix the package manager declaration in package.json");
  }
  const lockfiles = Object.fromEntries(SUPPORTED.map((name) => [name, lockfilesOf(root, LOCKFILES[name])]));
  const others = Object.entries(OTHER_LOCKFILES).filter(([, names]) => lockfilesOf(root, names).length > 0).map(([name]) => name);

  if (declarations.length > 0) {
    const names = new Set(declarations.map((d) => d.name));
    if (names.size > 1) {
      return blocked(
        `package.json declares different package managers: ${declarations.map((d) => `${d.source} ${d.name}`).join(", ")}`,
        "make packageManager and devEngines.packageManager name the same manager",
      );
    }
    const name = declarations[0].name;
    if (!SUPPORTED.includes(name)) {
      return blocked(`package.json declares ${name}; omt worktree setup supports only Bun and pnpm`, "write the worktree setup script by hand");
    }
    const specs = declarations.filter((d) => d.spec !== undefined && d.spec !== "");
    let version;
    let declaredBy;
    for (const d of specs) {
      if (parseVersion(d.spec) === undefined) {
        return blocked(
          `${d.source} gives ${name} version "${d.spec}", which is not an exact version; omt cannot check that it supports a global virtual store`,
          `pin an exact ${name} version of ${MINIMUM_VERSIONS[name]} or later, or write the worktree setup script by hand`,
        );
      }
      if (version !== undefined && version !== d.spec) {
        return blocked(`package.json declares ${name} ${version} and ${d.spec}`, "make the declared versions the same");
      }
      version = d.spec;
      declaredBy = d.source;
    }
    const minimum = minimumVersion(name, version);
    if (version !== undefined && compareVersions(version, minimum) < 0) {
      return blocked(
        `${declaredBy} pins ${name} ${version}; worktree setup needs ${name} ${minimum} or later`,
        `upgrade the pinned ${name} version to ${minimum} or later`,
      );
    }
    const lockfile = lockfiles[name][0];
    if (lockfile === undefined) {
      return blocked(`package.json declares ${name}, but ${LOCKFILES[name].join(" or ")} is missing`, `run ${name} install and commit the lockfile`);
    }
    return { status: "ok", manager: name, lockfile, ...(version === undefined ? {} : { version, declaredBy }) };
  }

  const found = SUPPORTED.filter((name) => lockfiles[name].length > 0);
  if (found.length > 1) {
    return blocked(
      `both ${found.map((name) => lockfiles[name][0]).join(" and ")} exist, and package.json declares no package manager`,
      "remove the lockfile you do not use, or set packageManager in package.json",
    );
  }
  if (found.length === 1) {
    const name = found[0];
    return { status: "ok", manager: name, lockfile: lockfiles[name][0] };
  }
  if (others.length > 0) {
    return blocked(`the lockfile belongs to ${others.join(" and ")}; omt worktree setup supports only Bun and pnpm`, "write the worktree setup script by hand");
  }
  if (pkg !== undefined) {
    return blocked("package.json exists, but there is no pnpm-lock.yaml, bun.lock, or bun.lockb", "install with Bun or pnpm and commit the lockfile");
  }
  return { status: "none", message: "no package.json or lockfile; there are no dependencies to install" };
}

// Removes a comment that starts outside a quoted string. In .npmrc and YAML a comment marker
// needs whitespace before it; in TOML it does not.
function stripComment(value, markers, needsSpace = true) {
  let quote;
  for (let i = 0; i < value.length; i++) {
    const char = value[i];
    if (quote !== undefined) {
      if (char === "\\" && quote === '"') i++;
      else if (char === quote) quote = undefined;
    } else if (char === '"' || char === "'") {
      quote = char;
    } else if (markers.includes(char) && (!needsSpace || i === 0 || /\s/.test(value[i - 1]))) {
      return value.slice(0, i);
    }
  }
  return value;
}

// A plain or quoted scalar. Returns undefined for any other form.
function scalar(raw) {
  const value = raw.trim();
  if (value === "") return undefined;
  if (value.startsWith('"')) {
    if (!/^"(?:[^"\\]|\\.)*"$/.test(value)) return undefined;
    try {
      return JSON.parse(value);
    } catch {
      return undefined;
    }
  }
  if (value.startsWith("'")) return /^'[^']*'$/.test(value) ? value.slice(1, -1) : undefined;
  if (/^[A-Za-z0-9._-]+$/.test(value)) return value;
  return undefined;
}

// .npmrc: `node-linker=<value>` lines, outside any section.
function npmrcLinker(text) {
  let section = false;
  let value;
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === "" || line.startsWith(";") || line.startsWith("#")) continue;
    if (/^\[.*\]$/.test(line)) {
      section = true;
      continue;
    }
    const match = /^([^=]+?)\s*=(.*)$/.exec(line);
    const mentions = /node-?linker/i.test(line);
    if (match === null) {
      if (mentions) return { unverified: line };
      continue;
    }
    const key = match[1].trim();
    if (!/^(node-linker|nodeLinker)$/.test(key)) continue;
    const parsed = scalar(stripComment(match[2], ";#"));
    if (section || parsed === undefined || parsed.includes("${")) return { unverified: line };
    value = parsed;
  }
  return value === undefined ? undefined : { value };
}

// pnpm-workspace.yaml: a top-level `<key>: <scalar>` line.
function yamlSetting(text, key) {
  let value;
  for (const raw of text.split(/\r?\n/)) {
    if (raw.trim().startsWith("#") || !raw.includes(key)) continue;
    const match = new RegExp(`^(["']?)${key}\\1\\s*:(.*)$`).exec(raw);
    if (match === null) return { unverified: raw.trim() };
    const parsed = scalar(stripComment(match[2], "#"));
    if (parsed === undefined || value !== undefined) return { unverified: raw.trim() };
    value = parsed;
  }
  return value === undefined ? undefined : { value };
}

function yamlLinker(text) {
  return yamlSetting(text, "nodeLinker");
}

// pnpm checks node_modules before `pnpm run` and `pnpm exec` and re-installs it when the settings
// differ from the install. A global store that only the setup's flags select then becomes a local
// store again. A setting in pnpm-workspace.yaml keeps it.
// pnpm 11.23.0 and later read virtualStoreType, which wins over enableGlobalVirtualStore when both are set.
// Older pnpm ignores virtualStoreType and reads only enableGlobalVirtualStore.
// `version` is the exact pnpm version: the declared one in a check, the installed one in the runner.
// Without it, a file whose result depends on the version is "version-dependent".
// Returns { status, message, action? } with status "set", "no-file" (omt worktree setup creates the file),
// "missing" (the file has no setting), "off", "version-dependent", or "unverified" (the file cannot be read).
export const PNPM_WORKSPACE_FILE = "pnpm-workspace.yaml";
export const PNPM_WORKSPACE_CONTENT = "enableGlobalVirtualStore: true\n";

export function persistentGlobalStore(root, version) {
  const path = join(root, PNPM_WORKSPACE_FILE);
  const canonical = version === undefined ? undefined : compareVersions(version, PNPM_CANONICAL_GLOBAL_STORE) >= 0;
  const action =
    canonical === false
      ? `add the top-level line \`enableGlobalVirtualStore: true\` to pnpm-workspace.yaml and commit it (pnpm ${version} ignores virtualStoreType); omt never changes an existing file`
      : `add the top-level line \`enableGlobalVirtualStore: true\` (or \`virtualStoreType: global\` with pnpm ${PNPM_CANONICAL_GLOBAL_STORE} or later) to pnpm-workspace.yaml and commit it; omt never changes an existing file`;
  const reset = "so a later pnpm run or pnpm exec can re-install node_modules with a local store";
  let text;
  try {
    text = readText(path);
  } catch (error) {
    return { status: "unverified", message: `cannot read pnpm-workspace.yaml (${error.code ?? error.message}), ${reset}`, action };
  }
  if (text === undefined) {
    let link = false;
    try {
      link = lstatSync(path).isSymbolicLink();
    } catch {}
    if (link) return { status: "unverified", message: `pnpm-workspace.yaml is a link to a missing file, ${reset}`, action };
    return {
      status: "no-file",
      message: `there is no pnpm-workspace.yaml to select the global virtual store, ${reset}`,
      action: "run omt worktree setup to create pnpm-workspace.yaml with `enableGlobalVirtualStore: true`, and commit it",
    };
  }
  const type = yamlSetting(text, "virtualStoreType");
  const legacy = yamlSetting(text, "enableGlobalVirtualStore");
  if (type?.unverified !== undefined || legacy?.unverified !== undefined) {
    return { status: "unverified", message: `pnpm-workspace.yaml sets the virtual store in a form omt cannot read (${type?.unverified ?? legacy?.unverified}), ${reset}`, action };
  }
  // The result for pnpm below 11.23.0, which reads only enableGlobalVirtualStore.
  const older = (() => {
    const ignored = type === undefined ? "" : ` (pnpm below ${PNPM_CANONICAL_GLOBAL_STORE} ignores virtualStoreType: ${type.value})`;
    if (legacy === undefined) {
      return { status: "missing", message: `pnpm-workspace.yaml does not set enableGlobalVirtualStore: true${ignored}, ${reset}`, action };
    }
    return String(legacy.value) === "true"
      ? { status: "set", message: "pnpm-workspace.yaml sets enableGlobalVirtualStore: true" }
      : { status: "off", message: `pnpm-workspace.yaml sets enableGlobalVirtualStore: ${legacy.value}${ignored}, ${reset}`, action };
  })();
  // The result for pnpm 11.23.0 and later, where virtualStoreType wins when it is set.
  const newer = (() => {
    if (type === undefined) {
      return older.status === "missing" ? { ...older, message: `pnpm-workspace.yaml does not select the global virtual store, ${reset}` } : older;
    }
    const over = legacy === undefined ? "" : `, which pnpm ${PNPM_CANONICAL_GLOBAL_STORE} and later use instead of enableGlobalVirtualStore: ${legacy.value}`;
    return String(type.value) === "global"
      ? { status: "set", message: `pnpm-workspace.yaml sets virtualStoreType: global${over}` }
      : {
          status: "off",
          message: `pnpm-workspace.yaml sets virtualStoreType: ${type.value}${over}, ${reset}`,
          action: "change virtualStoreType to global in pnpm-workspace.yaml, or remove it and keep the top-level line `enableGlobalVirtualStore: true`, and commit it; omt never changes an existing file",
        };
  })();
  if (canonical === true) return newer;
  if (canonical === false) return { ...older, message: older.message.replace(`pnpm below ${PNPM_CANONICAL_GLOBAL_STORE}`, `pnpm ${version}`) };
  if (older.status === newer.status) return newer;
  // Neither version selects the global store, so a version pin cannot help.
  if (older.status !== "set" && newer.status !== "set") {
    return {
      status: older.status === "off" || newer.status === "off" ? "off" : "missing",
      message: `pnpm-workspace.yaml does not select the global virtual store for any pnpm version (virtualStoreType: ${type?.value ?? "not set"}, enableGlobalVirtualStore: ${legacy?.value ?? "not set"}), ${reset}`,
      action: "set the top-level line `enableGlobalVirtualStore: true` in pnpm-workspace.yaml, and either remove virtualStoreType or set it to global, and commit it; omt never changes an existing file",
    };
  }
  const selects = newer.status === "set" ? `only with pnpm ${PNPM_CANONICAL_GLOBAL_STORE} or later` : `only with pnpm below ${PNPM_CANONICAL_GLOBAL_STORE}`;
  return {
    status: "version-dependent",
    message: `pnpm-workspace.yaml selects the global virtual store ${selects} (virtualStoreType: ${type?.value}, enableGlobalVirtualStore: ${legacy?.value ?? "not set"}), and package.json pins no exact pnpm version; the runner decides from the installed version`,
    action: "pin an exact pnpm version with packageManager in package.json, or set `enableGlobalVirtualStore: true` and either remove virtualStoreType or set it to global; omt never changes an existing file",
  };
}

function tomlKey(raw) {
  const parts = raw.split(".").map((part) => part.trim().replace(/^(["'])(.*)\1$/, "$2"));
  return parts.join(".");
}

// bunfig.toml: `linker = "<value>"` in `[install]`, or `install.linker` at the top level.
function tomlLinker(text) {
  let section = "";
  let value;
  for (const raw of text.split(/\r?\n/)) {
    const line = stripComment(raw, "#", false).trim();
    if (line === "") continue;
    const header = /^\[\s*([^\[\]]+?)\s*\]$/.exec(line);
    if (header !== null) {
      section = tomlKey(header[1]);
      continue;
    }
    if (line.startsWith("[")) {
      if (/install/.test(line)) return { unverified: raw.trim() };
      section = "[]";
      continue;
    }
    const match = /^([A-Za-z0-9_\-."' ]+?)\s*=(.*)$/.exec(line);
    if (match === null) {
      if (/linker/.test(line)) return { unverified: raw.trim() };
      continue;
    }
    const key = section === "" ? tomlKey(match[1]) : `${section}.${tomlKey(match[1])}`;
    if (key !== "install.linker") {
      if (/linker/.test(match[2])) return { unverified: raw.trim() };
      continue;
    }
    const parsed = scalar(match[2]);
    if (parsed === undefined || !/^\s*["']/.test(match[2])) return { unverified: raw.trim() };
    value = parsed;
  }
  return value === undefined ? undefined : { value };
}

function globalBunfigs(env, home) {
  const paths = [];
  if (env.XDG_CONFIG_HOME) paths.push(join(env.XDG_CONFIG_HOME, ".bunfig.toml"));
  if (home) paths.push(join(home, ".bunfig.toml"));
  return paths;
}

function linkerResult(source, found) {
  if (found.unverified !== undefined) {
    return {
      status: "unverified",
      source,
      message: `${source} sets the linker in a form omt cannot read: ${found.unverified}`,
      action: `write the linker setting in ${source} as one plain line, or write the worktree setup script by hand`,
    };
  }
  const value = String(found.value).trim().toLowerCase();
  if (value === "isolated") return { status: "isolated", source, message: `${source} selects the isolated linker` };
  return {
    status: "incompatible",
    source,
    value,
    message: `${source} selects the ${value} linker; a global virtual store needs the isolated linker`,
    action: `check that the project works with the isolated linker, then change ${source}; omt never changes it`,
  };
}

// Reads a config file that can set the linker. Returns { text } (text is undefined when the file
// is absent) or { result } with an "unverified" result when the file exists but cannot be read.
function readConfig(path, source) {
  try {
    return { text: readText(path) };
  } catch (error) {
    return {
      result: {
        status: "unverified",
        source,
        message: `cannot read ${source} (${error?.code ?? error?.message ?? error}), so its linker setting is unverified`,
        action: `make ${source} readable, then run the setup again`,
      },
    };
  }
}

// Checks the explicit linker settings that apply to the checkout. Returns { status, message, action?, source? }
// with status "default" (none set), "isolated", "incompatible", or "unverified".
export function checkLinker(root, manager, { env = {}, home } = {}) {
  if (manager === "pnpm") {
    for (const [key, value] of Object.entries(env)) {
      if (/^(npm|pnpm)_config_node[-_]linker$/i.test(key) && value !== undefined && value !== "") {
        const result = linkerResult(`the ${key} environment variable`, { value });
        if (result.status !== "isolated") return result;
      }
    }
    const sources = [
      [".npmrc", npmrcLinker],
      ["pnpm-workspace.yaml", yamlLinker],
    ];
    let isolated;
    for (const [name, parse] of sources) {
      const { text, result: unreadable } = readConfig(join(root, name), name);
      if (unreadable !== undefined) return unreadable;
      if (text === undefined) continue;
      const found = parse(text);
      if (found === undefined) continue;
      const result = linkerResult(name, found);
      if (result.status !== "isolated") return result;
      isolated = result;
    }
    return isolated ?? { status: "default", message: "no linker setting in the checkout; the setup selects the isolated linker" };
  }
  if (manager === "bun") {
    const { text: local, result: localUnreadable } = readConfig(join(root, "bunfig.toml"), "bunfig.toml");
    if (localUnreadable !== undefined) return localUnreadable;
    const localFound = local === undefined ? undefined : tomlLinker(local);
    if (localFound !== undefined) return linkerResult("bunfig.toml", localFound);
    for (const path of globalBunfigs(env, home)) {
      const { text, result: unreadable } = readConfig(path, path);
      if (unreadable !== undefined) return unreadable;
      if (text === undefined) continue;
      const found = tomlLinker(text);
      if (found !== undefined) return linkerResult(path, found);
    }
    return { status: "default", message: "no linker setting in bunfig.toml; the setup selects the isolated linker" };
  }
  return { status: "default", message: "no package manager" };
}

// The install command for the version that is actually installed.
export function installCommand(manager, version) {
  if (manager === "bun") {
    return { name: "bun", args: ["install", "--linker", "isolated", "--frozen-lockfile"], env: { BUN_INSTALL_GLOBAL_STORE: "1" } };
  }
  const canonical = compareVersions(version, PNPM_CANONICAL_GLOBAL_STORE) >= 0;
  const args = [
    "install",
    "--frozen-lockfile",
    "--config.node-linker=isolated",
    canonical ? "--config.virtual-store-type=global" : "--config.enable-global-virtual-store=true",
  ];
  if (compareVersions(version, "11.0.0") >= 0) args.push("--pm-on-fail=error");
  else args.push("--config.manage-package-manager-versions=false", "--config.package-manager-strict-version=true");
  return { name: "pnpm", args, env: {} };
}

function envValue(env, name) {
  const key = Object.keys(env).find((k) => k.toUpperCase() === name.toUpperCase());
  return key === undefined ? undefined : env[key];
}

// How to start a package manager. On Windows a .cmd shim needs cmd.exe; the arguments are fixed
// strings from installCommand, never text from package.json.
export function launchSpec(name, args, { platform = process.platform, env = process.env, exists = isFile } = {}) {
  if (platform !== "win32") return { file: name, args, options: {} };
  for (const arg of args) {
    if (!/^[A-Za-z0-9._=-]+$/.test(arg)) throw new Error(`unsafe argument for cmd.exe: ${arg}`);
  }
  const dirs = (envValue(env, "PATH") ?? "").split(";").filter((dir) => dir !== "");
  for (const dir of dirs) {
    for (const ext of [".exe", ".cmd", ".bat"]) {
      const full = `${dir.replace(/[\\/]+$/, "")}\\${name}${ext}`;
      if (!exists(full)) continue;
      if (ext === ".exe") return { file: full, args, options: {} };
      if (/["%!^\r\n]/.test(full)) throw new Error(`unsafe path for cmd.exe: ${full}`);
      return {
        file: envValue(env, "ComSpec") ?? "cmd.exe",
        args: ["/d", "/s", "/c", `""${full}" ${args.join(" ")}"`],
        options: { windowsVerbatimArguments: true },
      };
    }
  }
  return { file: `${name}.exe`, args, options: {} };
}

function isTruthy(value) {
  return value !== undefined && value !== "" && value !== "0" && value.toLowerCase() !== "false";
}

// pnpm's .modules.yaml records the layout of node_modules. A local layout needs a purge before
// a global-store install, and pnpm purges without asking when CI is set, so stop first.
function layoutProblem(root, manager) {
  const modules = join(root, "node_modules");
  let entries;
  try {
    entries = readdirSync(modules);
  } catch {
    return undefined;
  }
  if (entries.length === 0) return undefined;
  if (manager === "bun") {
    return entries.includes(".bun") ? undefined : "node_modules has a hoisted layout (no node_modules/.bun)";
  }
  const state = readText(join(modules, ".modules.yaml"));
  if (state === undefined) return "node_modules was not installed by pnpm (no node_modules/.modules.yaml)";
  const linker = /"?nodeLinker"?\s*:\s*"?([A-Za-z-]+)"?/.exec(state)?.[1];
  if (linker !== undefined && linker !== "isolated") return `node_modules has the ${linker} layout`;
  const store = /"?virtualStoreDir"?\s*:\s*"?([^",\r\n]+)"?/.exec(state)?.[1]?.trim();
  if (store !== undefined) {
    const full = resolve(modules, store);
    if (full === modules || full.startsWith(`${modules}/`) || full.startsWith(`${modules}\\`)) {
      return "node_modules has a local virtual store";
    }
  }
  return undefined;
}

function run(spawn, spec, cwd, env, capture) {
  return spawn(spec.file, spec.args, {
    cwd,
    env,
    stdio: capture ? ["ignore", "pipe", "pipe"] : ["ignore", "inherit", "inherit"],
    encoding: "utf8",
    ...(capture ? { timeout: 60_000 } : {}),
    ...spec.options,
  });
}

function failure(result) {
  if (result.error !== undefined) return result.error.code === "ENOENT" ? "not found on PATH" : result.error.message;
  if (result.signal) return `stopped by ${result.signal}`;
  return `exit code ${result.status}`;
}

// Runs the whole setup. Returns the exit code.
export function runSetup({
  root,
  env = process.env,
  home = homedir(),
  platform = process.platform,
  spawn = spawnSync,
  exists = isFile,
  out = (text) => process.stdout.write(text),
  err = (text) => process.stderr.write(text),
}) {
  const say = (text) => out(`omt-worktree-setup: ${text}\n`);
  const fail = (text, action) => {
    err(`omt-worktree-setup: ${text}\n`);
    if (action !== undefined) err(`omt-worktree-setup: next: ${action}\n`);
    return 1;
  };
  const found = detectManager(root);
  if (found.status === "none") {
    say(`${found.message}; nothing to do`);
    return 0;
  }
  if (found.status !== "ok") return fail(found.message, found.action);
  const { manager, lockfile } = found;
  const linker = checkLinker(root, manager, { env, home });
  if (linker.status === "incompatible" || linker.status === "unverified") return fail(linker.message, linker.action);
  if (manager === "pnpm") {
    // Without an exact declared version, a version-dependent result waits for the installed version.
    const store = persistentGlobalStore(root, found.version);
    if (store.status !== "set" && store.status !== "version-dependent") return fail(`${store.message}; nothing was installed`, store.action);
  }
  const layout = layoutProblem(root, manager);
  if (layout !== undefined) {
    return fail(
      `${layout}; the install would convert it`,
      `review ${join(root, "node_modules")}, remove that checkout's node_modules yourself, and run the setup again`,
    );
  }

  const childEnv = { ...env, ...NO_DOWNLOAD_ENV };
  let probeSpec;
  try {
    probeSpec = launchSpec(manager, ["--version"], { platform, env: childEnv, exists });
  } catch (error) {
    return fail(error.message);
  }
  const probe = run(spawn, probeSpec, root, childEnv, true);
  if (probe.error !== undefined || probe.status !== 0) {
    const detail = `${probe.stdout ?? ""} ${probe.stderr ?? ""}`.replace(/\s+/g, " ").trim().slice(0, 600);
    return fail(
      `${manager} --version failed (${failure(probe)})${detail === "" ? "" : `: ${detail}`}`,
      `install ${manager} ${found.version ?? `${MINIMUM_VERSIONS[manager]} or later`} and put it on PATH; this setup downloads no package manager`,
    );
  }
  const actual = String(probe.stdout ?? "").trim().split(/\r?\n/).pop()?.trim().replace(/^v/, "") ?? "";
  const core = /^(\d+\.\d+\.\d+)/.exec(actual)?.[1];
  if (core === undefined) return fail(`${manager} --version printed "${actual}", which is not a version`);
  const minimum = minimumVersion(manager, core);
  if (compareVersions(core, minimum) < 0) {
    return fail(
      `${manager} ${actual} is installed; worktree setup needs ${manager} ${minimum} or later`,
      `upgrade ${manager}; this setup installs no package manager`,
    );
  }
  if (found.version !== undefined && actual !== found.version) {
    return fail(
      `${found.declaredBy} pins ${manager} ${found.version}, but ${manager} ${actual} is on PATH`,
      `install ${manager} ${found.version} and put it on PATH; this setup downloads no package manager`,
    );
  }

  if (manager === "pnpm") {
    const query = run(spawn, launchSpec("pnpm", ["config", "get", "node-linker"], { platform, env: childEnv, exists }), root, childEnv, true);
    if (query.error !== undefined || query.status !== 0) {
      const detail = `${query.stdout ?? ""} ${query.stderr ?? ""}`.replace(/\s+/g, " ").trim().slice(0, 600);
      return fail(
        `pnpm config get node-linker failed (${failure(query)})${detail === "" ? "" : `: ${detail}`}; the effective linker is unknown, so nothing was installed`,
        "fix the pnpm config so that pnpm config get node-linker succeeds in this checkout, then run the setup again",
      );
    }
    const value = String(query.stdout ?? "").trim().split(/\r?\n/).pop()?.trim() ?? "";
    if (!["", "undefined", "isolated"].includes(value)) {
      return fail(
        `the effective pnpm config selects the ${value} linker; a global virtual store needs the isolated linker`,
        "check that the project works with the isolated linker, then change the pnpm config; this setup never changes it",
      );
    }
    const store = persistentGlobalStore(root, core);
    if (store.status !== "set") return fail(`${store.message}; nothing was installed`, store.action);
    if (compareVersions(core, PNPM_CANONICAL_GLOBAL_STORE) < 0 && isTruthy(envValue(env, "CI"))) {
      err(`omt-worktree-setup: warning: pnpm ${actual} can turn off the global virtual store when CI is set; pnpm ${PNPM_CANONICAL_GLOBAL_STORE} or later keeps it\n`);
    }
  }

  const command = installCommand(manager, core);
  const installEnv = { ...childEnv, ...command.env };
  let spec;
  try {
    spec = launchSpec(command.name, command.args, { platform, env: installEnv, exists });
  } catch (error) {
    return fail(error.message);
  }
  say(`${manager} ${actual}, ${lockfile}: ${[...Object.entries(command.env).map(([k, v]) => `${k}=${v}`), command.name, ...command.args].join(" ")}`);
  const result = run(spawn, spec, root, installEnv, false);
  if (result.error !== undefined || result.signal) return fail(`${manager} install failed (${failure(result)})`);
  if (result.status !== 0) {
    fail(
      `${manager} install failed (exit code ${result.status})`,
      `read the ${manager} output above; when it says node_modules must be removed, review and remove that checkout's node_modules, then run the setup again`,
    );
    return result.status;
  }
  say("dependencies installed");
  return 0;
}

function realOrSelf(path) {
  try {
    return realpathSync(path);
  } catch {
    return resolve(path);
  }
}

// The omt CLI bundles this file, so in dist/cli.js or a binary, `self` is the CLI itself. Only the
// .mjs runner file runs the setup.
const self = fileURLToPath(import.meta.url);
if (self.endsWith(".mjs") && process.argv[1] !== undefined && existsSync(process.argv[1]) && realOrSelf(process.argv[1]) === realOrSelf(self)) {
  // Node resolves symlinks in the script path, so a linked .t3 folder or runner moves `self`
  // out of the checkout that started it. Stop instead of installing in the wrong folder.
  const root = dirname(dirname(self));
  const started = realOrSelf(dirname(dirname(resolve(process.argv[1]))));
  if (started !== realOrSelf(root)) {
    process.stderr.write(
      `omt-worktree-setup: ${process.argv[1]} is reached through a symlink, so it would work on ${root} instead of ${started}; nothing was installed\n` +
        "omt-worktree-setup: next: replace the symlinked .t3 folder or runner with a real folder and file, then run the setup again\n",
    );
    process.exitCode = 1;
  } else {
    process.exitCode = runSetup({ root });
  }
}
